const meta = $json.snapshot_meta || {};
const leadsCount = parseInt(meta.leads_count || 0, 10);
const postsCount = parseInt(meta.posts_count || 0, 10);
const usersCount = parseInt(meta.users_count || 0, 10);
const dbSize = meta.db_size || 'Bilinmiyor';

// Veri Bütünlüğü Doğrulaması: Kritik tablolarda ani veri sıfırlanması olmamalıdır
const isDataIntegrityOk = usersCount > 0;

return [{
  json: {
    timestamp: new Date().toISOString(),
    leadsCount,
    postsCount,
    categoriesCount: meta.categories_count || 0,
    usersCount,
    referencesCount: meta.references_count || 0,
    auditLogsCount: meta.audit_logs_count || 0,
    dbSize,
    isDataIntegrityOk,
    status: isDataIntegrityOk ? 'SUCCESS' : 'INTEGRITY_FAIL',
    summary: `Veritabanı Snapshot: ${leadsCount} Lead, ${postsCount} Post, ${meta.references_count} Referans, ${usersCount} Kullanıcı. Boyut: ${dbSize}.`
  }
}];
